// src/routes/posts/new.tsx
import { s } from '@pyreon/validate'
import { defineAction, Form, useSubmission } from '@pyreon/zero/actions'
import { db } from '../../server/db'

export const action = defineAction(
  s.object({ title: s.string().min(3), tags: s.array(s.string()) }),
  async (input) => db.posts.insert(input), // input: { title: string; tags: string[] }
)

export default function NewPost() {
  const sub = useSubmission(action)
  const titleError = () => {
    const r = sub.result()
    return r && 'fields' in r ? (r.fields.title?.join(', ') ?? '') : ''
  }
  return (
    <Form action={action}>
      <input name="title" />
      <p>{titleError}</p>
      <input name="tags" value="news" />
      <input name="tags" value="release" />
      <button>Publish</button>
    </Form>
  )
}
